syllabus.codeExample:
# web/modules/custom/jes_projects/jes_projects.info.yml
name: 'JES Projects'
description: 'Custom project management module'
package: Custom
type: module
core_version_requirement: ^10

# jes_projects.module
use Drupal\Core\Entity\EntityInterface;

/**
 * Implements hook_node_presave().
 * Auto-sets project reference on save.
 */
function jes_projects_node_presave(EntityInterface $node) {
  if ($node->bundle() === 'project_report') {
    if ($node->get('field_access')->isEmpty()) {
      $node->set('field_access', 'alpha');
    }
  }
}

{# themes/custom/jes_theme/templates/node--project-report.html.twig #}
<article class="project-card {{ node.bundle }}" id="node-{{ node.id }}">
  <header class="project-header">
    <h2 class="project-title">{{ label }}</h2>
    {% if content.field_access %}
      <span class="access-badge">
        {{ content.field_access }}
      </span>
    {% endif %}
  </header>
  <div class="project-body">
    {{ content.body }}
  </div>
  {{ content.field_project_categories }}
</article>

# Role permission matrix in config
# user.role.editor.yml
id: editor
label: Editor
weight: 2
permissions:
  - 'create project_report content'
  - 'edit own project_report content'
  - 'delete own project_report content'
  - 'access content overview'

# Programmatic access check in custom route
public function access(AccountInterface $account): AccessResult {
  return AccessResult::allowedIf(
    $account->hasPermission('administer projects')
  )->cachePerPermissions();
}
